/**
 * Gallery source → .utpkg (the same format Automations → Packages builds):
 * assets in the config-as-code layout, sample rows as package data,
 * requirements generated by lib/packages/requirements, signed with the
 * "UserTasks Gallery" ed25519 key when one is given.
 *
 * Builds are deterministic: every timestamp is the release date of the
 * version (gallery.json changelog), so the same sources give the same bytes
 * and the same checksum — `npm run gallery:check` relies on that.
 */

/* eslint-disable @typescript-eslint/no-explicit-any -- manifests are free-form JSON */

import { createHash, createPrivateKey } from 'node:crypto'
import { stringifyForRepo } from '@/lib/github-sync/layout'
import { countAssets, findSecretLeaks, PACKAGE_SECTIONS, toPackageFiles, type PackageContents } from '@/lib/packages/build'
import { keyFingerprint, packPackage, publicKeyBase64, type PackageFileManifest, type PackageRequirement } from '@/lib/packages/format'
import { detectRequirements, type DetectContext } from '@/lib/packages/requirements'
import { scanAssetReferences } from '@/lib/portability/dependencies'
import type { GallerySource } from './source'

export const GALLERY_AUTHOR = 'UserTasks Gallery'

export interface GallerySigningKey {
  privateKeyPem: string
  publicKey: string
  fingerprint: string
}

/** Parse GALLERY_SIGNING_KEY (PEM; literal `\n` escapes allowed). Throws on a non-ed25519 key. */
export function parseGallerySigningKey(pem: string | undefined | null): GallerySigningKey | null {
  const clean = String(pem ?? '').replace(/\\n/g, '\n').trim()
  if (!clean) return null
  const key = createPrivateKey(clean)
  if (key.asymmetricKeyType !== 'ed25519') throw new Error('GALLERY_SIGNING_KEY must be an ed25519 private key (PEM, PKCS#8)')
  const publicKey = publicKeyBase64(key)
  return { privateKeyPem: clean, publicKey, fingerprint: keyFingerprint(publicKey) }
}

export function galleryFileName(slug: string, version: string): string {
  return `${slug}-${version}.utpkg`
}

/** Release date (YYYY-MM-DD) of the package's current version. */
export function releaseDate(source: GallerySource): string {
  const entry = (source.meta.changelog ?? []).find((item) => item.version === source.meta.version)
  return entry?.date ?? '1970-01-01'
}

/** Package sections only (no table_rows / format_version), as the install side reads them. */
export function packageAssets(manifest: Record<string, any>): Record<string, any> {
  const assets: Record<string, any> = {}
  for (const section of PACKAGE_SECTIONS) if (Array.isArray(manifest[section]) && manifest[section].length) assets[section] = manifest[section]
  return assets
}

/** People (assignees / teams) referenced in the assets: they become `user` requirements. */
export function galleryPeople(assets: Record<string, any>): NonNullable<DetectContext['people']> {
  const people: NonNullable<DetectContext['people']> = []
  for (const section of PACKAGE_SECTIONS) {
    for (const asset of Array.isArray(assets[section]) ? assets[section] : []) {
      for (const person of scanAssetReferences(asset).people) people.push({ ...person, section, asset_id: String(asset.id) })
    }
  }
  const seen = new Set<string>()
  return people.filter((person) => {
    const key = `${person.asset_id}:${person.path.join('.')}`
    if (seen.has(key)) return false
    seen.add(key)
    return true
  })
}

/**
 * Requirements as the package builder would generate them, with one gallery
 * rule on top: assignees are required. A gallery workflow ships with
 * placeholder people, so a step without a real assignee could never create
 * its task; leaving one empty keeps the install incomplete instead.
 */
export function galleryRequirements(assets: Record<string, any>): PackageRequirement[] {
  return detectRequirements(assets, { people: galleryPeople(assets), systemRoles: [] }).map((requirement) => (
    requirement.kind === 'user'
      ? { ...requirement, required: true, description: 'Users never travel in a package: pick who receives each of these steps (a user in this workspace, by email or id). The workflow stays inactive until they are set.' }
      : requirement
  ))
}

export function galleryContents(source: GallerySource): PackageContents {
  const { meta } = source
  const assets = packageAssets(source.manifest)
  const rowsByTable = new Map<string, any[]>()
  for (const entry of Array.isArray(source.manifest.table_rows) ? source.manifest.table_rows : []) {
    rowsByTable.set(String(entry.id), Array.isArray(entry.rows) ? entry.rows : [])
  }
  const data: PackageContents['data'] = {}
  for (const table of assets.data_tables ?? []) {
    const rows = rowsByTable.get(String(table.id))
    data[String(table.id)] = rows ? { mode: 'rows', rows: rows.map((row) => ({ id: String(row.id), data: row.data ?? {} })) } : { mode: 'schema' }
  }
  return {
    header: {
      id: meta.id,
      name: meta.title,
      slug: meta.slug,
      version: meta.version,
      description: meta.summary,
      author: GALLERY_AUTHOR,
      created_at: `${releaseDate(source)}T00:00:00.000Z`,
      ...(meta.icon ? { icon: meta.icon } : {}),
      readme: source.readme,
    },
    assets,
    data,
    requirements: galleryRequirements(assets),
    dependencies: [],
  }
}

/**
 * "No integrations needed": built-in features only — no REST integration,
 * connector, AI agent or MCP server, and no install-time requirement (no
 * credentials, URLs or placeholder people), so an install is complete as
 * soon as it lands.
 */
export function isNativeContents(contents: Pick<PackageContents, 'assets' | 'requirements'>): boolean {
  const a = contents.assets as Record<string, unknown[] | undefined>
  return !(a.integrations?.length || a.connectors?.length || a.agents?.length || a.mcp_servers?.length || a.log_destinations?.length) && contents.requirements.length === 0
}

export interface BuiltGalleryPackage {
  slug: string
  fileName: string
  bytes: Uint8Array
  /** sha256 of the file bytes (hex). */
  sha256: string
  manifest: PackageFileManifest
  contents: PackageContents
  assetCount: number
  files: Array<{ path: string; content: string }>
}

/** Pin every envelope / index timestamp to the release date (deterministic output). */
function pinTimestamps(files: Array<{ path: string; content: string }>, stamp: string) {
  return files.map((file) => {
    if (!file.path.startsWith('assets/') || !file.path.endsWith('.json')) return file
    const parsed = JSON.parse(file.content)
    if (parsed && typeof parsed === 'object' && 'exported_at' in parsed) parsed.exported_at = stamp
    return { path: file.path, content: stringifyForRepo(parsed) }
  })
}

export function buildGalleryPackage(source: GallerySource, options: { signingKey?: GallerySigningKey | null } = {}): BuiltGalleryPackage {
  const contents = galleryContents(source)
  const laidOut = toPackageFiles(contents)
  const files = pinTimestamps(laidOut.files, contents.header.created_at)
  const leaks = findSecretLeaks(files)
  if (leaks.length) throw new Error(`${source.slug}: refusing to build, credential material in ${leaks.slice(0, 5).join(', ')}`)
  const packed = packPackage({ header: laidOut.header, files, signingKeyPem: options.signingKey?.privateKeyPem ?? null })
  return {
    slug: source.slug,
    fileName: galleryFileName(source.meta.slug, source.meta.version),
    bytes: packed.bytes,
    sha256: createHash('sha256').update(packed.bytes).digest('hex'),
    manifest: packed.manifest,
    contents,
    assetCount: countAssets(contents.assets),
    files: packed.files,
  }
}
